insert into public.narrative (id, body, updated_by) values (1, 'A Escola (@missaojosue.educacao) fala com quem ensina criança: FIMC, o portal do aluno e a matrícula. A Missão (@missaojosue.ofc) mostra os campos e a vida da igreja. O Esdras traz ideia na segunda e na quinta; a Isabelle confirma o que entra na grade.', 'Isabelle');
